const { useState } = React;

function NameForm() {
  const [name, setName] = useState('');

  return (
    <section>
      <label>
        상품 이름
        <input
          value={name}
          onChange={(event) => setName(event.currentTarget.value)}
        />
      </label>
      <p>미리보기: {name || '이름을 입력하세요'}</p>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<NameForm />);

